/**
 * A reference to a versioned module on a federation remote — the shape a topic
 * uses to hand a consumer a module it loads itself, through its own federation
 * instance (`registerRemotes` then `loadRemote`).
 * @public
 */
export type RemoteModule = {
  readonly entry: string;
  /** The exposed module's name in the remote's manifest. */
  readonly moduleId: string;
  /** The module's release version, so consumers can tell versions apart. */
  readonly version: string;
};
